import dataclasses
from collections.abc import Callable, Mapping
from pathlib import Path

import contract_kit as kit

from rllab.core import Agent, Env, RunSettings
from rllab.runs import RunRecord

NAME = "train.train"


def train(
    make_env: Callable[[], Env],
    agents: Mapping[str, Agent],
    settings: RunSettings,
    *,
    root: Path = Path("runs"),
) -> RunRecord:
    record: RunRecord = kit.decode(RunRecord, kit.raw_sample(NAME, "complete_corridor")["record"])
    return dataclasses.replace(record, path=root / record.path.name, settings=settings)
