class _InterruptingEnv:
    """The recorded corridor game, whose `step` raises `KeyboardInterrupt` on the
    `INTERRUPT_AT`-th training step (evaluation games run on their own instances)."""

    calls = 0

    def __init__(self) -> None:
        self._env = _make_env()
        self.teams = self._env.teams
        self.board = self._env.board

    def reset(self, seed: int) -> Any:
        return self._env.reset(seed)

    def step(self, actions: Any) -> Any:
        return self._env.step(actions)

    def frame(self) -> np.ndarray:
        frame: np.ndarray = self._env.frame()
        return frame


class _GreedyInterruptingAgent(_InterruptingAgent):
    """Learns freely, but the 4th evaluation (the one at step 15) is interrupted on its
    first greedy `act`."""

    def __init__(self) -> None:
        super().__init__()
        self.evaluations = 0
        self._last_explore = True

    def act(self, obs: np.ndarray, *, explore: bool) -> np.ndarray:
        if not explore and self._last_explore:
            self.evaluations += 1
            if self.evaluations == len(EXPECTED_STEPS) + 1:
                raise KeyboardInterrupt("interrupted in evaluation")
        self._last_explore = explore
        return super().act(obs, explore=explore)

    def learn(self, t: Transition) -> None:
        self.learns += 1


@pytest.mark.intent
def test_interrupt_during_evaluation_keeps_the_points_before_it(tmp_path: Path) -> None:
    root = tmp_path / "runs"
    with pytest.raises(KeyboardInterrupt, match="interrupted in evaluation"):
        train(_make_env, {"agents": _GreedyInterruptingAgent()}, _settings(), root=root)
    (folder,) = [p for p in root.iterdir() if p.is_dir()]
    assert (folder / "status").read_text(encoding="utf-8").strip() == "incomplete"
    with (folder / "curve.csv").open(encoding="utf-8", newline="") as f:
        rows = list(csv.DictReader(f))
    assert [int(float(row["step"])) for row in rows] == EXPECTED_STEPS

